            check("".equals(host("fixture-host").get("environmentId"))&&"Sem ambiente".equals(host("fixture-host").get("environmentName")),"legacy host unassigned");check(((Number)((Map)host("fixture-host").get("settingsOverrides")).get("maxFiles")).intValue()==4321&&((List)view().get("runtimes")).size()==1,"migration preserves overrides and inventory");ok(call("GET","/api/agent/settings?hostId=fixture-host",null,false,"fixture-agent-token"),200,"legacy auth preserved");
            check(call("POST","/api/environments",map("name","Forbidden"),false,null)[0].equals(401),"environment auth");String csrf=ServerTest.csrf;ServerTest.csrf="bad";check(call("POST","/api/environments",map("name","Forbidden"),true,null)[0].equals(403),"environment CSRF");ServerTest.csrf=csrf;
            Map dev=ok(call("POST","/api/environments",map("name","Desenv","description","Development","settings",map("maxFiles",2300,"includePaths",Arrays.asList("/opt/dev"))),true,null),201,"create dev"),prod=ok(call("POST","/api/environments",map("name","Produção","settings",map("maxFiles",2400,"includePaths",Arrays.asList("/opt/prod"))),true,null),201,"create prod");String d=(String)dev.get("id"),p=(String)prod.get("id");
            check(call("POST","/api/environments",map("name"," desenv "),true,null)[0].equals(409),"case-insensitive duplicate rejected");check(call("PUT","/api/environments",map("environmentId",p,"name","DESENV"),true,null)[0].equals(409),"rename duplicate rejected");String html="<img src=x onerror=alert(1)>";Map literal=ok(call("PUT","/api/environments",map("environmentId",d,"description",html),true,null),200,"literal description");check(html.equals(literal.get("description")),"HTML stored as text not executed by server");
            check(download(map("environmentId",d),false)[0].equals(401),"package auth");ServerTest.csrf="bad";check(download(map("environmentId",d),true)[0].equals(403),"package CSRF");ServerTest.csrf=csrf;
            Properties first=bootstrap(d,2,"assessment-desenv.zip"),second=bootstrap(d,2,"assessment-desenv.zip"),production=bootstrap(p,1,"assessment-producao.zip");check(!first.getProperty("enrollmentToken").equals(second.getProperty("enrollmentToken")),"repeat downloads have independent codes");ZipFile generic=new ZipFile(new File(root,"dist/assessment-collector.zip"));check(generic.getEntry("conf/bootstrap.properties")==null,"shared generic archive stays secret-free");generic.close();
            Map firstHost=registered("environment-install-01",first,p),secondHost=registered("environment-install-02",production,d);String h1=(String)firstHost.get("hostId"),h2=(String)secondHost.get("hostId"),t1=(String)firstHost.get("agentToken"),t2=(String)secondHost.get("agentToken");check(d.equals(host(h1).get("environmentId"))&&p.equals(host(h2).get("environmentId")),"membership from validated enrollment not collector");
            Map repeat=registered("environment-install-01",first,p);check(h1.equals(repeat.get("hostId"))&&t1.equals(repeat.get("agentToken")),"same-package replay stable");check(call("POST","/api/agent/register",EnrollmentTest.registration("environment-install-01"),false,second.getProperty("enrollmentToken"))[0].equals(409),"different package cannot recover host credential by UUID");Map third=registered("environment-install-03",second,p);check(d.equals(host((String)third.get("hostId")).get("environmentId")),"new package retains same permanent environment");
            ok(call("PUT","/api/settings",map("pauseMillis",7,"maxFiles",3000),true,null),200,"global settings");Map effective=(Map)host(h1).get("settings");check(((Number)effective.get("pauseMillis")).intValue()==7&&((Number)effective.get("maxFiles")).intValue()==2300,"global then environment inheritance");check(((Map)host(h1).get("settingsOverrides")).isEmpty(),"environment settings not copied into host overrides");
            ok(call("PUT","/api/hosts/settings",map("hostId",h1,"settings",map("maxFiles",1111)),true,null),200,"host override");ok(call("PUT","/api/environments",map("environmentId",d,"settings",map("maxFiles",2500,"includePaths",Arrays.asList("/opt/changed"))),true,null),200,"environment settings replace");check(((Number)((Map)host(h1).get("settings")).get("maxFiles")).intValue()==1111,"host wins over environment");
            ok(call("PUT","/api/hosts/settings",map("hostId",h1,"settings",map(),"replaceOverrides",true),true,null),200,"reset host overrides");check(((Number)((Map)host(h1).get("settings")).get("maxFiles")).intValue()==2500,"reset resumes inheritance");ok(call("PUT","/api/hosts/settings",map("hostId",h1,"settings",map("batchSize",12)),true,null),200,"move keeps override");
            ok(call("PUT","/api/hosts/environment",map("hostId",h1,"environmentId",p),true,null),200,"reassign host");check(p.equals(host(h1).get("environmentId"))&&((Number)((Map)host(h1).get("settings")).get("maxFiles")).intValue()==2400&&((Number)((Map)host(h1).get("settings")).get("batchSize")).intValue()==12,"assignment updates inheritance preserves overrides");registered("environment-install-01",first,d);check(p.equals(host(h1).get("environmentId")),"old registration retry cannot undo admin reassignment");
            check(call("PUT","/api/hosts/environment",map("hostId",h2,"environmentId",d),false,t1)[0].equals(401),"collector cannot reassign hosts");ok(call("PUT","/api/hosts/environment",map("hostId",h1,"environmentId",""),true,null),200,"remove assignment");check("".equals(host(h1).get("environmentId")),"unassigned allowed");check(call("PUT","/api/hosts/environment",map("hostId",h1,"environmentId","unknown"),true,null)[0].equals(404),"unknown environment rejected");
            ok(call("PUT","/api/environments",map("environmentId",p,"settings",map("enabled",true,"frequency","daily","windowStart","00:00","windowEnd","00:00")),true,null),200,"environment schedule");String job=(String)ok(call("GET","/api/agent/poll?hostId="+h2,null,false,t2),200,"scheduled production poll").get("jobId");check(job!=null,"environment schedule inherited");Map result=EnrollmentTest.snapshot(h2,job,"21.0.12","environment-event-prod");((Map)result.get("host")).put("environmentId",d);ok(call("POST","/api/agent/results",result,false,t2),200,"production result");check(p.equals(host(h2).get("environmentId")),"snapshot cannot forge environment");ok(call("PUT","/api/environments",map("environmentId",d,"settings",map("maxFiles",2800)),true,null),200,"different environment changed");check(ok(call("GET","/api/agent/poll?hostId="+h2,null,false,t2),200,"repeat production poll").get("jobId")==null,"other environment revision does not repeat production schedule");ok(call("PUT","/api/environments",map("environmentId",p,"name","Production renamed"),true,null),200,"rename production");check(ok(call("GET","/api/agent/poll?hostId="+h2,null,false,t2),200,"poll after rename").get("jobId")==null,"rename preserves schedule slot");ok(call("PUT","/api/environments",map("environmentId",p,"settings",map()),true,null),200,"clear environment overrides");check(((Number)((Map)host(h2).get("settings")).get("maxFiles")).intValue()==3000,"empty environment settings resumes global defaults");
