            // Expired/revoked enrollment retention may be pruned; host credentials must remain usable.
            Map registry=(Map)EnrollmentTest.privateField(EnrollmentTest.privateField(ServerTest.app,"registry"),"registry"),codes=(Map)registry.get("enrollments");String firstId=null;for(Object item:codes.values()){Map e=(Map)item;if(d.equals(e.get("environmentId"))&&((Number)e.get("usedCount")).intValue()>0){firstId=(String)e.get("id");break;}}ok(call("POST","/api/enrollments/revoke",map("enrollmentId",firstId),true,null),200,"revoke package");check(call("POST","/api/agent/register",EnrollmentTest.registration("environment-install-04"),false,first.getProperty("enrollmentToken"))[0].equals(403),"revoked package rejected");ok(call("GET","/api/agent/settings?hostId="+h1,null,false,t1),200,"registered host survives bootstrap revocation");
            for(int i=codes.size();i<EnrollmentRegistry.MAX_ENROLLMENTS;i++)codes.put("expired-"+i,map("id","expired-"+i,"status","active","expiresMillis",1,"usedCount",1));bootstrap(p,1,"assessment-production-renamed.zip");check(codes.size()<EnrollmentRegistry.MAX_ENROLLMENTS,"expired used codes pruned at bound");ok(call("GET","/api/agent/settings?hostId="+h2,null,false,t2),200,"host survives enrollment retention");
            String exported=Json.stringify(ok(call("GET","/api/export",null,true,null),200,"export"));for(String secret:new String[]{first.getProperty("enrollmentToken"),second.getProperty("enrollmentToken"),t1,t2,"agentToken","installationId","tokenHash"})check(exported.indexOf(secret)<0,"export excludes secrets");
